import{_ as t,o as e,c as i,a2 as l}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"实时互动","description":"","frontmatter":{},"headers":[],"relativePath":"features/interaction.md","filePath":"features/interaction.md","lastUpdated":1785772843000}'),r={name:"features/interaction.md"};function o(h,a,n,d,s,b){return e(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="实时互动" tabindex="-1">实时互动 <a class="header-anchor" href="#实时互动" aria-label="Permalink to &quot;实时互动&quot;">​</a></h1><h2 id="功能概述" tabindex="-1">功能概述 <a class="header-anchor" href="#功能概述" aria-label="Permalink to &quot;功能概述&quot;">​</a></h2><p>在 ZViewer 房间里，你和好友不仅可以同步看视频，还能实时互动——发弹幕、聊天、语音、甚至用画笔在画面上圈画。</p><hr><h2 id="一、评论与聊天" tabindex="-1">一、评论与聊天 <a class="header-anchor" href="#一、评论与聊天" aria-label="Permalink to &quot;一、评论与聊天&quot;">​</a></h2><p>评论面板在房间界面的<strong>右侧面板</strong>（CommentPanel），包含三个 Tab。</p><h3 id="如何发送评论" tabindex="-1">如何发送评论 <a class="header-anchor" href="#如何发送评论" aria-label="Permalink to &quot;如何发送评论&quot;">​</a></h3><ol><li>确保处于 <strong>「评论区」Tab</strong></li><li>在底部的输入框中输入文字</li><li>按回车或点击发送按钮</li><li>评论会立即显示，房间内所有人都能看到</li></ol><h2 id="二、弹幕系统" tabindex="-1">二、弹幕系统 <a class="header-anchor" href="#二、弹幕系统" aria-label="Permalink to &quot;二、弹幕系统&quot;">​</a></h2><p>弹幕是飘过视频画面的滚动文字评论。</p><h3 id="弹幕的三个来源" tabindex="-1">弹幕的三个来源 <a class="header-anchor" href="#弹幕的三个来源" aria-label="Permalink to &quot;弹幕的三个来源&quot;">​</a></h3><table tabindex="0"><thead><tr><th>来源</th><th>说明</th></tr></thead><tbody><tr><td>Bilibili 官方弹幕</td><td>从 Bilibili 拉取的原视频弹幕</td></tr><tr><td>DandanPlay 弹幕</td><td>第三方弹幕库，聚合多个来源</td></tr><tr><td>自定义弹幕</td><td>你和好友在房间内发送的实时弹幕</td></tr></tbody></table><h3 id="加载-bilibili-弹幕" tabindex="-1">加载 Bilibili 弹幕 <a class="header-anchor" href="#加载-bilibili-弹幕" aria-label="Permalink to &quot;加载 Bilibili 弹幕&quot;">​</a></h3><p>添加 Bilibili 视频后，弹幕会自动加载，从视频画面右向左飘过。</p><h3 id="发送自定义弹幕" tabindex="-1">发送自定义弹幕 <a class="header-anchor" href="#发送自定义弹幕" aria-label="Permalink to &quot;发送自定义弹幕&quot;">​</a></h3><p>在右侧面板的 <strong>「实时弹幕」Tab</strong> 中输入文字发送，所有观众都能看到。</p><h3 id="弹幕轨道管理" tabindex="-1">弹幕轨道管理 <a class="header-anchor" href="#弹幕轨道管理" aria-label="Permalink to &quot;弹幕轨道管理&quot;">​</a></h3><p>在 <strong>「弹幕轨道」Tab</strong> 中可屏蔽关键词、调整弹幕样式（字体/颜色/透明度/速度）、关闭某个弹幕轨道。</p><h2 id="三、观众申请控制" tabindex="-1">三、观众申请控制 <a class="header-anchor" href="#三、观众申请控制" aria-label="Permalink to &quot;三、观众申请控制&quot;">​</a></h2><p>作为观众，如果你想快进/后退或暂停，可以向房主发送申请。</p><ol><li>在播放器上点击暂停/跳转进度</li><li>系统提示&quot;已向房主发送申请，请等待确认&quot;</li><li>房主的播放器左上角显示通知</li><li>房主点击同意或拒绝</li></ol><p>如果房主开启了 <strong>「自动通过控制请求」</strong>，申请会自动生效。</p><h2 id="四、语音聊天" tabindex="-1">四、语音聊天 <a class="header-anchor" href="#四、语音聊天" aria-label="Permalink to &quot;四、语音聊天&quot;">​</a></h2><p>语音面板（VoiceChatPanel）常驻在页面<strong>右下角</strong>。</p><h3 id="房主开启语音" tabindex="-1">房主开启语音 <a class="header-anchor" href="#房主开启语音" aria-label="Permalink to &quot;房主开启语音&quot;">​</a></h3><ol><li>点击右下角语音面板</li><li>开启语音</li><li>设置比特率：32 / 96 / 128 / 192 kbps</li><li>开启后观众可收听</li></ol><h3 id="观众收听" tabindex="-1">观众收听 <a class="header-anchor" href="#观众收听" aria-label="Permalink to &quot;观众收听&quot;">​</a></h3><p>语音面板中会显示成员列表，可调节扬声器音量。</p><h2 id="五、屏幕标注" tabindex="-1">五、屏幕标注 <a class="header-anchor" href="#五、屏幕标注" aria-label="Permalink to &quot;五、屏幕标注&quot;">​</a></h2><p>在屏幕共享模式下，房主可以使用画笔工具在画面上圈画重点，所有观众实时看到。</p><h2 id="六、播放状态同步" tabindex="-1">六、播放状态同步 <a class="header-anchor" href="#六、播放状态同步" aria-label="Permalink to &quot;六、播放状态同步&quot;">​</a></h2><p>作为观众加入房间后，一切自动同步：</p><ul><li>房主播放/暂停/跳转/倍速 → 你自动跟随</li><li>房主断线后服务器接管广播，观看不中断</li><li>房主离线超 10 分钟房间自动关闭</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="弹幕不显示" tabindex="-1">弹幕不显示？ <a class="header-anchor" href="#弹幕不显示" aria-label="Permalink to &quot;弹幕不显示？&quot;">​</a></h3><p>确认视频已加载，检查弹幕轨道是否已加载，尝试重新添加视频。</p><h3 id="语音听不到声音" tabindex="-1">语音听不到声音？ <a class="header-anchor" href="#语音听不到声音" aria-label="Permalink to &quot;语音听不到声音？&quot;">​</a></h3><p>确认房主已开启语音，检查扬声器，检查麦克风权限，尝试 HTTPS 访问。</p><h3 id="发送的申请房主没反应" tabindex="-1">发送的申请房主没反应？ <a class="header-anchor" href="#发送的申请房主没反应" aria-label="Permalink to &quot;发送的申请房主没反应？&quot;">​</a></h3><p>房主可能不在，稍等片刻。如果开启了自动通过，申请会自动生效。</p>',40)])])}const p=t(r,[["render",o]]);export{u as __pageData,p as default};
